#include <stdio.h>

/* world is 40x28 with a dead border row/column all round */
int cur[30][42];
int nxt[30][42];
int W = 40;
int H = 28;

void emit_frame() {
    /* pack 4 cells per hex digit, row-major: 40*28/4 = 280 digits */
    printf("\"");
    for (int y = 1; y <= H; y++) {
        for (int x = 1; x <= W; x += 4) {
            int nib = cur[y][x] * 8 + cur[y][x + 1] * 4 + cur[y][x + 2] * 2 + cur[y][x + 3];
            printf("%x", nib);
        }
    }
    printf("\"");
}

int main() {
    for (int y = 0; y < 30; y++)
        for (int x = 0; x < 42; x++) { cur[y][x] = 0; nxt[y][x] = 0; }

    /* r-pentomino near the centre - the famous long-lived starter */
    cur[13][20] = 1; cur[13][21] = 1;
    cur[14][19] = 1; cur[14][20] = 1;
    cur[15][20] = 1;

    /* light deterministic soup in the corners so edges stay lively */
    int seed = 4242;
    for (int y = 1; y <= H; y++) {
        for (int x = 1; x <= W; x++) {
            seed = (seed * 75 + 74) % 65537;
            int corner = (x < 12 || x > W - 11) && (y < 9 || y > H - 8);
            if (corner && seed % 100 < 22) cur[y][x] = 1;
        }
    }

    int gens = 40;
    printf("__NB_SET__ {\"key\":\"life\",\"value\":{\"w\":%d,\"h\":%d,\"frames\":[", W, H);
    emit_frame();

    int population = 0;
    for (int g = 0; g < gens; g++) {
        for (int y = 1; y <= H; y++) {
            for (int x = 1; x <= W; x++) {
                int n = cur[y-1][x-1] + cur[y-1][x] + cur[y-1][x+1]
                      + cur[y][x-1]                 + cur[y][x+1]
                      + cur[y+1][x-1] + cur[y+1][x] + cur[y+1][x+1];
                if (cur[y][x] == 1) nxt[y][x] = (n == 2 || n == 3) ? 1 : 0;
                else                nxt[y][x] = (n == 3) ? 1 : 0;
            }
        }
        population = 0;
        for (int y = 1; y <= H; y++)
            for (int x = 1; x <= W; x++) { cur[y][x] = nxt[y][x]; population += nxt[y][x]; }
        printf(",");
        emit_frame();
    }
    printf("]}}\n");
    printf("simulated %d generations, final population %d\n", gens, population);
    return 0;
}
